window.IELTSQuestionMaterialChunks.push([{"part":"p2","title":"A popular person","question":"Describe a popular person. \n \nYou should say: \nWho he/she is \nWhat he/she has done or does \nWhy he/she is popular \nAnd explain how you feel about him/her","points":[{"prompt":"Who he/she is","idea":"班里受欢迎的同学小林，认识两年"},{"prompt":"What he/she has done or does","idea":"她给新同学介绍校园，主动邀请他们参加午餐"},{"prompt":"Why he/she is popular","idea":"受欢迎是因为能记住别人名字，别人紧张时会认真听"},{"prompt":"And explain how you feel about him/her","idea":"我欣赏她让人感到被接纳，而不只是外向"}],"expressions":{"B1":"make people feel welcome","B2":"put others at ease","C1":"create a sense of belonging"},"angles":["Communication","Personality"]},{"part":"p2","title":"An athlete/sports team you admire","question":"Describe an athlete/ sports team you admire. \nYou should say \nWho/What the athlete/sports team is \nWhere/How you got to know the athlete/sports team \nHow often you watch their sports games \nAnd explain why you admire the athlete/sports team","points":[{"prompt":"Who/What the athlete/sports team is","idea":"校篮球队，第一次在学校决赛看到他们"},{"prompt":"Where/How you got to know the athlete/sports team","idea":"我从同学邀请和校园海报知道这支队伍"},{"prompt":"How often you watch their sports games","idea":"赛季里每个月看一两场，平时看比赛集锦"},{"prompt":"And explain why you admire the athlete/sports team","idea":"落后时仍互相鼓励，坚持防守让我佩服"}],"expressions":{"B1":"never give up","B2":"work well as a team","C1":"show resilience under pressure"},"angles":["Strength","Sentimental"]},{"part":"p2","title":"Someone you have helped to become healthier","question":"Describe someone you have helped to become healthier or fitter. \nYou should say: \nWho this person was \nWhy you helped him/her \nHow you helped him/her \nAnd explain how you felt about the result","points":[{"prompt":"Who this person was","idea":"经常久坐的室友，最近觉得容易累"},{"prompt":"Why you helped him/her","idea":"我想帮他建立日常活动习惯，而不是让他快速减重"},{"prompt":"How you helped him/her","idea":"我们晚饭后走二十分钟，并记录每周次数"},{"prompt":"And explain how you felt about the result","idea":"一个月后他更愿意出门，我为他坚持下来高兴"}],"expressions":{"B1":"go for a walk","B2":"build a sustainable routine","C1":"make gradual lifestyle changes"},"angles":["Health","Communication"]},{"part":"p2","title":"A person who taught you something","question":"Describe a person who taught you something. \nYou should say:\nwho the person was\nwhere you met him or her \nwhat this person taught you\nand explain how you felt about what he or she taught you","points":[{"prompt":"who the person was","idea":"大学社团的摄影老师，在周末活动认识"},{"prompt":"where you met him or her","idea":"在大学摄影社的周末活动认识她，当时我正在尝试拍人像"},{"prompt":"what this person taught you","idea":"她教我利用窗边的自然光拍人像；先示范角度，再让我拍同一对象比较"},{"prompt":"and explain how you felt about what he or she taught you","idea":"我从怕犯错变成愿意尝试，实际反馈很有帮助"}],"expressions":{"B1":"learn by doing","B2":"give constructive feedback","C1":"break a complex skill into manageable steps"},"angles":["Education","Strength"]},{"part":"p2","title":"An old person you know and respect","question":"Describe an old person you know and respect. \n \nYou should say: \nWho this person is \nHow you know this person \nWhat he or she is like \nAnd explain why you respect this person","points":[{"prompt":"Who this person is","idea":"楼下的退休邻居，搬家时认识"},{"prompt":"How you know this person","idea":"搬家时他帮我熟悉小区，我们后来常在楼下碰面"},{"prompt":"What he or she is like","idea":"他耐心、谦虚，会修小家电，也会承认自己不懂手机功能"},{"prompt":"And explain why you respect this person","idea":"我尊重他的耐心和愿意继续学习的态度"}],"expressions":{"B1":"be patient with people","B2":"share practical experience","C1":"remain open to new ideas"},"angles":["Personality","Education"]},{"part":"p2","title":"A person who likes to make things by hand","question":"Describe a person who likes to make things by hand (e.g. toys, furniture). \nYou should say: \nWho this person is \nWhat he/she makes \nWhy he/she likes to make things by hand \nAnd explain how you feel about the person","points":[{"prompt":"Who this person is","idea":"叔叔喜欢手工制作，在家有一张工作台"},{"prompt":"What he/she makes","idea":"他用旧木板做书架，也修理破损的椅子"},{"prompt":"Why he/she likes to make things by hand","idea":"喜欢按房间尺寸定做，觉得动手比直接购买有成就感"},{"prompt":"And explain how you feel about the person","idea":"我欣赏他的耐心，成品小瑕疵反而有个人特色"}],"expressions":{"B1":"make things by hand","B2":"restore old furniture","C1":"take pride in craftsmanship"},"angles":["Interest","Strength"]},{"part":"p2","title":"A person who enjoys learning history","question":"Describe a person who enjoys learning history. \nYou should say: \nWho this person is \nHow he/she learns history \nWhy he/she loves history \nAnd explain how you feel about him/her","points":[{"prompt":"Who this person is","idea":"大学同学对历史感兴趣，常一起逛博物馆"},{"prompt":"How he/she learns history","idea":"他读人物传记，看历史纪录片，再对照展品说明"},{"prompt":"Why he/she loves history","idea":"他想知道普通人过去怎样生活，不只记年代"},{"prompt":"And explain how you feel about him/her","idea":"和他聊天让我发现同一事件可以有不同解释"}],"expressions":{"B1":"visit a museum","B2":"compare different accounts","C1":"put events in historical context"},"angles":["Education","Interest"]},{"part":"p2","title":"An organized person","question":"Describe an organized person. \nYou should say: \nWho this person is \nHow you knew this person \nWhat he/she does to be organized \nAnd explain how you feel about this person","points":[{"prompt":"Who this person is","idea":"一起做项目的同学，我在课堂分组认识她"},{"prompt":"How you knew this person","idea":"我在课堂小组项目中认识她，第一次会议就发现她会提前准备"},{"prompt":"What he/she does to be organized","idea":"她把截止日期写进日历，列优先任务；文件按日期命名，会后确认负责人"},{"prompt":"And explain how you feel about this person","idea":"我觉得和她合作省心，也学会提前留出缓冲时间"}],"expressions":{"B1":"make a to-do list","B2":"set clear priorities","C1":"anticipate potential setbacks"},"angles":["Strength","Profession"]},{"part":"p2","title":"A person you know who really likes taking photos","question":"Describe a person you know who really likes taking photos. \nYou should say: \nWho the person is \nWhen and how you got to know him/her \nWhere he/she takes photos \nAnd explain how you feel about him/her","points":[{"prompt":"Who the person is","idea":"高中朋友，在学校摄影社认识"},{"prompt":"When and how you got to know him/her","idea":"高中时在学校摄影社认识，经常一起参加周末拍摄活动"},{"prompt":"Where he/she takes photos","idea":"她常在街道和公园拍摄，喜欢早晨柔和的光，也会先征求拍摄对象的同意"},{"prompt":"And explain how you feel about him/her","idea":"我喜欢她能注意到普通人忽略的小细节"}],"expressions":{"B1":"take photos of daily life","B2":"capture natural expressions","C1":"notice overlooked details"},"angles":["Interest","Personality"]},{"part":"p2","title":"A person you only met once","question":"Describe a person you only met once and want to know more about. \n \nYou should say: \nWho he/she is \nWhen you met him/her \nWhy you want to know more about him/her \nAnd explain how you feel about him/her","points":[{"prompt":"Who he/she is","idea":"在一次徒步活动只见过一次的志愿者"},{"prompt":"When you met him/her","idea":"上个月在集合点，他帮我确认路线"},{"prompt":"Why you want to know more about him/her","idea":"他讲了如何准备长途徒步，我想了解他的旅行经历"},{"prompt":"And explain how you feel about him/her","idea":"他很友善又没有炫耀，我希望以后能再交流"}],"expressions":{"B1":"meet someone by chance","B2":"strike up a conversation","C1":"leave a lasting impression"},"angles":["Communication","Interest"]},{"part":"p2","title":"A person who did something difficult and was successful","question":"Describe a person you know who did something difficult and was successful. \nYou should say: \nWho this person is \nWhat difficult thing this person did \nWhy this person was successful \nAnd explain how you feel about this person","points":[{"prompt":"Who this person is","idea":"朋友第一次组织社区义卖，我认识她多年"},{"prompt":"What difficult thing this person did","idea":"难点是预算少、志愿者时间不一致，还要联系场地"},{"prompt":"Why this person was successful","idea":"她提前分工并准备雨天备用方案，活动顺利完成"},{"prompt":"And explain how you feel about this person","idea":"我佩服她把大问题拆成小任务，遇到变化不慌"}],"expressions":{"B1":"solve one problem at a time","B2":"coordinate a small team","C1":"remain resourceful under pressure"},"angles":["Strength","Profession"]},{"part":"p2","title":"A happy person you know","question":"Describe a happy person you know. \nYou should say: \nWho this person is \nWhat he/she is like \nHow he/she shows happiness \nAnd explain why you think he/she is a happy person","points":[{"prompt":"Who this person is","idea":"总是很乐观的表姐，周末常一起吃饭"},{"prompt":"What he/she is like","idea":"她容易相处，也愿意讲生活中的小趣事"},{"prompt":"How he/she shows happiness","idea":"她会笑着感谢别人的帮助，下雨也能想到室内活动"},{"prompt":"And explain why you think he/she is a happy person","idea":"她不是没有烦恼，而是能从小事找到快乐"}],"expressions":{"B1":"enjoy the little things","B2":"look on the bright side","C1":"maintain a positive outlook"},"angles":["Personality","Sentimental"]},{"part":"p2","title":"A person who is good at learning and speaking new languages","question":"Describe a person who is good at learning and speaking new languages. \nYou should say: \nHow you got to know him/her \nHow he/she learns a new language \nWhat languages he/she can speak \nAnd explain how you feel about him/her","points":[{"prompt":"How you got to know him/her","idea":"在语言交换活动认识这位同学，我们后来一起练口语"},{"prompt":"How he/she learns a new language","idea":"他每天听短音频并跟读，把新词放进自己的句子"},{"prompt":"What languages he/she can speak","idea":"他能用英语交流，也在学习西班牙语；程度按真实情况替换"},{"prompt":"And explain how you feel about him/her","idea":"我佩服他敢于开口，并会主动请求纠错"}],"expressions":{"B1":"practise a little every day","B2":"learn through regular exposure","C1":"develop an ear for different accents"},"angles":["Education","Strength"]},{"part":"p2","title":"A successful business person you admire","question":"Describe a successful business person you admire. \n \nYou should say: \nWho this person is \nWhat kind of business this person does \nWhy this person are successful \nAnd explain why you admire this person","points":[{"prompt":"Who this person is","idea":"社区书店的店主，我通过买书认识她"},{"prompt":"What kind of business this person does","idea":"她经营小书店并举办读书活动"},{"prompt":"Why this person are successful","idea":"她了解附近居民需求，控制库存，并通过读书活动和认真听建议建立信任"},{"prompt":"And explain why you admire this person","idea":"我欣赏她把爱好变成可持续的服务，而不只看收入"}],"expressions":{"B1":"listen to customers","B2":"build customer loyalty","C1":"identify an underserved niche"},"angles":["Economy","Profession"]},{"part":"p2","title":"A person you know who loves to grow plants","question":"Describe a person you know who loves to grow plants (e.g. vegetables/fruits/flowers etc.). \n \nYou should say: \nWho this person is \nWhat he/she grows \nWhere he/she grows them \nAnd explain why he/she enjoys this activity","points":[{"prompt":"Who this person is","idea":"喜欢种植物的妈妈，在阳台摆花盆"},{"prompt":"What he/she grows","idea":"她种薄荷、小番茄和几盆花"},{"prompt":"Where he/she grows them","idea":"阳台有阳光，花盆底部留排水孔"},{"prompt":"And explain why he/she enjoys this activity","idea":"每天观察新叶让她放松，也能享受自己种的食物"}],"expressions":{"B1":"water the plants","B2":"grow herbs on a balcony","C1":"find satisfaction in nurturing plants"},"angles":["Health","Relaxation"]},{"part":"p2","title":"A person who has chosen a career in the medical field","question":"Describe a person who has chosen a career in the medical field (e.g. a doctor, a nurse). \nYou should say: \nWho her/she is \nWhat he/she does \nWhy he/she chose this career \nAnd explain how you feel about him/her","points":[{"prompt":"Who her/she is","idea":"在医院工作的表姐，是一名护士"},{"prompt":"What he/she does","idea":"她照顾病人、观察情况并向家属解释注意事项"},{"prompt":"Why he/she chose this career","idea":"小时候受到照顾她的护士影响，希望做有用的工作"},{"prompt":"And explain how you feel about him/her","idea":"我佩服她耐心沟通，也理解轮班工作的辛苦"}],"expressions":{"B1":"care for patients","B2":"provide emotional reassurance","C1":"handle emotionally demanding work"},"angles":["Profession","Communication"]},{"part":"p2","title":"Your favourite childhood friend","question":"Describe your favourite childhood friend. \n \nYou should say: \nWho he/she is \nWhere you met each other \nWhat you often did together \nAnd explain what made you like him/her","points":[{"prompt":"Who he/she is","idea":"小学同桌，在一年级教室认识"},{"prompt":"Where you met each other","idea":"我们放学后打羽毛球，也互相检查作业"},{"prompt":"What you often did together","idea":"有一次我忘带书，他主动和我共用"},{"prompt":"And explain what made you like him/her","idea":"我喜欢他可靠又幽默，和他相处不用假装"}],"expressions":{"B1":"share things with a friend","B2":"have a lot in common","C1":"form a lasting bond"},"angles":["Sentimental","Personality"]},{"part":"p2","title":"A recent change that helps you save time","question":"Describe a recent change in life that helps you save a lot of time. \n \nYou should say: \nWhat it is \nWhat you have done \nHow it helps you save time \nAnd explain how you feel about this change","points":[{"prompt":"What it is","idea":"最近开始提前准备第二天的午餐"},{"prompt":"What you have done","idea":"我周日列菜单并买齐食材，最近开始每晚提前分装午餐"},{"prompt":"How it helps you save time","idea":"早晨不用纠结吃什么，也减少排队买早餐的时间"},{"prompt":"And explain how you feel about this change","idea":"我觉得早上更从容；节省时间数字用自己的记录"}],"expressions":{"B1":"prepare things in advance","B2":"cut down on daily decisions","C1":"streamline my morning routine"},"angles":["Economy","Strength"]},{"part":"p2","title":"An occasion when you lost something in a public place","question":"Describe an occasion when you lost something in a public place. \n \nYou should say: \nWhat you lost \nWhen and where you lost it \nWhat you did to find it \nAnd explain how you feel about this experience","points":[{"prompt":"What you lost","idea":"上个月在公交车上忘了一把雨伞"},{"prompt":"When and where you lost it","idea":"下车后发现手里没有伞，想起座位旁的挂钩"},{"prompt":"What you did to find it","idea":"先回忆线路和下车时间，再联系失物招领处"},{"prompt":"And explain how you feel about this experience","idea":"找回时松了一口气，现在下车前检查座位"}],"expressions":{"B1":"leave something behind","B2":"contact the lost-property office","C1":"retrace my steps"},"angles":["Weakness","Sentimental"]},{"part":"p2","title":"A party you enjoyed","question":"Describe a party you enjoyed. \n \nYou should say: \nWhen you went to this party \nWhere the party was held \nWhat kind of party it was \nAnd explain why you enjoyed this party","points":[{"prompt":"When you went to this party","idea":"上周六去参加朋友的生日聚会"},{"prompt":"Where the party was held","idea":"地点是朋友家，人数不多，大家都比较熟悉"},{"prompt":"What kind of party it was","idea":"这是一个小型生日聚会，大家做饭、玩桌游，没有很吵的音乐"},{"prompt":"And explain why you enjoyed this party","idea":"我享受能认真聊天的气氛，不用和陌生人大量寒暄"}],"expressions":{"B1":"celebrate a birthday","B2":"enjoy a relaxed atmosphere","C1":"feel a genuine sense of connection"},"angles":["Communication","Relaxation"]},{"part":"p2","title":"A time when you changed an important decision","question":"Describe a time when you changed an important decision of yours. \nYou should say: \nWhen you changed the decision \nWhat the original decision was \nWhy you changed it \nAnd explain how you felt about the experience","points":[{"prompt":"When you changed the decision","idea":"去年报名课程前一周改变了决定"},{"prompt":"What the original decision was","idea":"原本想选价格最低的大班课"},{"prompt":"Why you changed it","idea":"试听后发现我更需要口语反馈，于是改选小班"},{"prompt":"And explain how you felt about the experience","idea":"虽然费用更高，但练习机会更多，我觉得决定值得"}],"expressions":{"B1":"change my mind","B2":"weigh up the options","C1":"reassess my priorities"},"angles":["Education","Economy"]},{"part":"p2","title":"A short trip you often do but you don’t like","question":"Describe a short trip you often do but you don’t like. \n \nYou should say: \nWhere you travel to \nHow often you do this trip \nWhy you need to do this trip \nAnd explain why you don’t like this trip","points":[{"prompt":"Where you travel to","idea":"每周两次坐公交到另一个校区上课"},{"prompt":"How often you do this trip","idea":"单程不算远，但要换车并等待"},{"prompt":"Why you need to do this trip","idea":"因为实验课安排在那里，无法在线完成"},{"prompt":"And explain why you don’t like this trip","idea":"高峰期拥挤又容易迟到，来回打断学习节奏"}],"expressions":{"B1":"change buses","B2":"deal with rush-hour traffic","C1":"find the commute disproportionately tiring"},"angles":["Weakness","Education"]},{"part":"p2","title":"A time when someone told you something you are not interested in","question":"Describe a time when someone told you something you were not interested in \n \nYou should say: \nWhen it happened \nWhere you heard it \nWhat you talked about \nAnd explain why you were not interested in it","points":[{"prompt":"When it happened","idea":"上周在午餐时，同事一直讲一款游戏"},{"prompt":"Where you heard it","idea":"他详细解释角色装备和升级规则"},{"prompt":"What you talked about","idea":"我没有玩过这款游戏，专有名词让我跟不上"},{"prompt":"And explain why you were not interested in it","idea":"我先礼貌听了一会儿，再问更容易理解的问题"}],"expressions":{"B1":"lose track of the conversation","B2":"struggle to relate to the topic","C1":"find the technical jargon inaccessible"},"angles":["Communication","Interest"]},{"part":"p2","title":"A time when you saved money to buy an expensive gift for others","question":"Describe a time when you saved money to buy an expensive gift for others. \n \nYou should say: \nWhat it was \nWhy you wanted to buy this gift \nHow long you saved money for it \nAnd explain how you felt when you bought the gift","points":[{"prompt":"What it was","idea":"给喜欢画画的妹妹买一套画笔"},{"prompt":"Why you wanted to buy this gift","idea":"她的旧画笔掉毛，我想支持她的兴趣"},{"prompt":"How long you saved money for it","idea":"我存了三个月零花钱，减少外卖并比较套装价格"},{"prompt":"And explain how you felt when you bought the gift","idea":"买到时很有成就感，看到她马上试画更开心"}],"expressions":{"B1":"save a little each week","B2":"stick to a savings plan","C1":"choose a thoughtful rather than extravagant gift"},"angles":["Economy","Sentimental"]},{"part":"p2","title":"A time when you received good service in a shop/store","question":"Describe a time when you received good service in a shop/store. \nYou should say: \nWhere the shop is \nWhen you went to the shop \nWhat service you received from the staff \nAnd explain how you felt about the service","points":[{"prompt":"Where the shop is","idea":"学校附近的一家鞋店"},{"prompt":"When you went to the shop","idea":"去年冬天我去买日常穿的鞋，试穿后发现鞋跟摩擦"},{"prompt":"What service you received from the staff","idea":"店员拿出不同尺码、解释材料，并让我走动测试，没有催我购买"},{"prompt":"And explain how you felt about the service","idea":"我觉得需求被认真对待，下次也愿意回来"}],"expressions":{"B1":"try on different sizes","B2":"receive attentive service","C1":"feel that my needs were genuinely understood"},"angles":["Communication","Economy"]},{"part":"p2","title":"An activity wastes your time","question":"Describe an activity you usually do that wastes your time. \n \nYou should say: \nWhat it is \nWhen you usually do it \nWhy you do it \nAnd explain why you think it wastes your time","points":[{"prompt":"What it is","idea":"睡前不停刷短视频"},{"prompt":"When you usually do it","idea":"原本只是想放松十分钟，却经常越刷越久"},{"prompt":"Why you do it","idea":"平台不断推荐新内容，让我很难停下来"},{"prompt":"And explain why you think it wastes your time","idea":"看完记不住多少内容，还挤占睡眠，所以设了时间提醒"}],"expressions":{"B1":"keep scrolling","B2":"lose track of time","C1":"fall into a cycle of passive consumption"},"angles":["Health","Weakness"]},{"part":"p2","title":"An enjoyable evening you had with your friends","question":"Describe an enjoyable evening you had with your friends. \nYou should say: \nWhen and where it was \nWhat you did \nWho you spent the evening with \nAnd explain why it was enjoyable","points":[{"prompt":"When and where it was","idea":"上个月周五在朋友家，和三位老同学聚会"},{"prompt":"What you did","idea":"我们做简餐、听歌，并分享各自工作近况"},{"prompt":"Who you spent the evening with","idea":"大家轮流讲趣事，没有一直看手机"},{"prompt":"And explain why it was enjoyable","idea":"久没见面却仍能自然聊天，让我觉得亲近又放松"}],"expressions":{"B1":"catch up with friends","B2":"share recent experiences","C1":"reconnect without feeling awkward"},"angles":["Communication","Sentimental"]},{"part":"p2","title":"A time you watched a famous person being interviewed","question":"Describe a time you watched a famous person being interviewed. \nYou should say: \nWho the famous person was \nWhat the interview was about \nWhen and where you watched the interview \nAnd explain how you felt about the experience","points":[{"prompt":"Who the famous person was","idea":"一位我熟悉的演员，名字替换成真正看过的人"},{"prompt":"What the interview was about","idea":"访谈讨论他第一次试镜失败后如何继续训练，包括排练和接受批评"},{"prompt":"When and where you watched the interview","idea":"上周我在手机视频平台看，节目比一般电影宣传更详细"},{"prompt":"And explain how you felt about the experience","idea":"我觉得比宣传电影更真实，也理解成功需要长期投入"}],"expressions":{"B1":"talk about a setback","B2":"give an honest account","C1":"reveal the effort behind public success"},"angles":["Education","Strength"]},{"part":"p2","title":"A new skill you learned when you were a child","question":"Describe a new skill you learned when you were a child. \nYou should say: \nWhat the skill was \nWho taught you this skill \nHow you learned it \nAnd explain how you felt about learning the skill","points":[{"prompt":"What the skill was","idea":"小学时学骑自行车"},{"prompt":"Who taught you this skill","idea":"爸爸在小区空地教我，先扶着后座陪我练"},{"prompt":"How you learned it","idea":"先练短距离直线，再练转弯；摔过几次后慢慢能独立保持平衡"},{"prompt":"And explain how you felt about learning the skill","idea":"第一次独立骑完一圈很自豪，也更敢尝试新事物"}],"expressions":{"B1":"keep my balance","B2":"build confidence through practice","C1":"overcome the fear of making mistakes"},"angles":["Education","Strength"]},{"part":"p2","title":"A lesson impressed you a lot","question":"Describe a lesson that impressed you a lot. \n \nYou should say: \nWhat the lesson was about \nWhere you took the lesson \nWhat you did in the lesson \nAnd explain why it impressed you a lot","points":[{"prompt":"What the lesson was about","idea":"关于水资源和过滤方法的一节科学课"},{"prompt":"Where you took the lesson","idea":"初中时在学校实验室上这节课"},{"prompt":"What you did in the lesson","idea":"我们分组比较材料，记录过滤前后的变化"},{"prompt":"And explain why it impressed you a lot","idea":"亲手做实验比背定义更容易记住，也看见了知识的用途"}],"expressions":{"B1":"do a simple experiment","B2":"connect theory with practice","C1":"make an abstract concept tangible"},"angles":["Education","Interest"]},{"part":"p2","title":"A time when you made an important decision","question":"Describe a time when you made an important decision and were happy with the result. \nYou should say: \nWhat the decision was \nWhy you made the decision \nHow easy it was for you to make the decision \nAnd explain why you were happy with the result","points":[{"prompt":"What the decision was","idea":"去年决定参加学校演讲比赛"},{"prompt":"Why you made the decision","idea":"我想练习在人前说话，而不是一直避开它"},{"prompt":"How easy it was for you to make the decision","idea":"一开始很犹豫，后来请朋友听我排练"},{"prompt":"And explain why you were happy with the result","idea":"比赛时虽然紧张却讲完了，现在做展示更自信"}],"expressions":{"B1":"take a small risk","B2":"step outside my comfort zone","C1":"gain confidence through a deliberate challenge"},"angles":["Strength","Education"]},{"part":"p2","title":"A happy event you organized","question":"Describe a happy event you organized. \n \nYou should say: \nWhat the event was \nWhen you had it \nWho helped you to organize it \nAnd explain how you feel about it","points":[{"prompt":"What the event was","idea":"为朋友组织的小型毕业聚会"},{"prompt":"When you had it","idea":"活动在上个月举行，我提前两周开始准备"},{"prompt":"Who helped you to organize it","idea":"同学帮忙做邀请和准备照片，我订地点并安排分享回忆的环节"},{"prompt":"And explain how you feel about it","idea":"看到平时安静的同学也愿意发言，我觉得准备很值得"}],"expressions":{"B1":"plan a get-together","B2":"share the workload","C1":"bring people together through shared memories"},"angles":["Communication","Sentimental"]},{"part":"p2","title":"A special day out that did not cost you much","question":"Describe a special day out that didn't cost you much. \n \nYou should say: \nWhen the day was \nWhere you went \nHow much you spent \nAnd explain how you feel about that day","points":[{"prompt":"When the day was","idea":"上个周日，天气很好"},{"prompt":"Where you went","idea":"我和朋友坐公交去附近公园野餐，带了家里的水果和三明治"},{"prompt":"How much you spent","idea":"只花了车费和少量饮料钱，金额按真实经历改"},{"prompt":"And explain how you feel about that day","idea":"沿湖散步和聊天让我放松，快乐不一定来自昂贵消费"}],"expressions":{"B1":"have a picnic","B2":"enjoy a low-cost day out","C1":"appreciate simple pleasures"},"angles":["Economy","Relaxation"]},{"part":"p2","title":"A time when you received a message or email and it took you a long time to reply","question":"Describe a time when you received a message or email and it took you a long time to reply. \nYou should say: \nWho this person was \nWhat the message/email was about \nWhy you spent a lot of time replying \nAnd explain how you felt about the experience","points":[{"prompt":"Who this person was","idea":"老师发邮件问我是否愿意参加新项目"},{"prompt":"What the message/email was about","idea":"邮件需要确认时间、任务和能否出席"},{"prompt":"Why you spent a lot of time replying","idea":"我先查看课表，再和家人商量，所以过了两天才回复"},{"prompt":"And explain how you felt about the experience","idea":"我有点担心显得不礼貌，回复时解释了原因并致谢"}],"expressions":{"B1":"check my schedule","B2":"give a considered reply","C1":"avoid making a commitment prematurely"},"angles":["Communication","Profession"]},{"part":"p2","title":"A challenging technological problem you faced","question":"Describe a challenging technological problem you faced. \nYou should say: \nWhat the problem was \nWhen and where you faced it \nHow challenging it was \nAnd explain how you solved it","points":[{"prompt":"What the problem was","idea":"在线展示前，电脑突然无法连接网络"},{"prompt":"When and where you faced it","idea":"当时在教室，距离展示开始只有十分钟"},{"prompt":"How challenging it was","idea":"时间紧，又需要播放在线资料；检查连接和重启后仍没有恢复"},{"prompt":"And explain how you solved it","idea":"最后改用手机热点并准备离线幻灯片，展示顺利；以后会提前备份"}],"expressions":{"B1":"restart the computer","B2":"switch to a mobile hotspot","C1":"have a contingency plan in place"},"angles":["Strength","Profession"]},{"part":"p2","title":"An important decision you made in life","question":"Describe an important decision you made in life. \n \nYou should say: \nWhat the decision was \nWhy you made this decision \nHow you made this decision \nAnd explain why this decision was important","points":[{"prompt":"What the decision was","idea":"毕业前决定先实习再选长期工作方向"},{"prompt":"Why you made this decision","idea":"我不确定自己更适合教学还是内容设计"},{"prompt":"How you made this decision","idea":"比较岗位内容，问前辈，再通过短期实习体验日常任务"},{"prompt":"And explain why this decision was important","idea":"这个决定影响后续学习和求职，比只看职位名称更实际"}],"expressions":{"B1":"ask for advice","B2":"make an informed choice","C1":"align a decision with long-term priorities"},"angles":["Profession","Education"]},{"part":"p2","title":"A live sports event you watched before","question":"Describe a live sports event you watched before \n \nYou should say: \nWhen it happened \nWhere it took place \nWho you watched it with \nAnd explain how you felt about this experience","points":[{"prompt":"When it happened","idea":"上学期的学校篮球决赛"},{"prompt":"Where it took place","idea":"地点在学校体育馆，我们坐在靠近场边的看台"},{"prompt":"Who you watched it with","idea":"我和两位同学一起看，最后一节比分接近，大家一起欢呼"},{"prompt":"And explain how you felt about this experience","idea":"现场气氛比手机看集锦更有感染力，让我很兴奋"}],"expressions":{"B1":"cheer for a team","B2":"experience the atmosphere firsthand","C1":"feel a collective surge of excitement"},"angles":["Relaxation","Sentimental"]},{"part":"p2","title":"A plan that you had to change recently","question":"Describe a plan that you had to change recently. \nYou should say: \nWhen this happened \nWhat made you change the plan \nWhat the new plan was \nAnd how you felt about the change","points":[{"prompt":"When this happened","idea":"上周末原计划去山里徒步"},{"prompt":"What made you change the plan","idea":"出发前看到天气预报有大雨，决定避免风险"},{"prompt":"What the new plan was","idea":"改成去室内攀岩馆，通知同行朋友并取消车票"},{"prompt":"And how you felt about the change","idea":"有点失望，但仍能一起活动，也觉得自己处理得及时"}],"expressions":{"B1":"check the weather forecast","B2":"make an alternative plan","C1":"adapt without losing the main purpose"},"angles":["Health","Strength"]},{"part":"p2","title":"A time when you worked in a group","question":"Describe a time when you worked in a group. \nYou should say: \nWhat you did \nWho you worked with \nWhat problems you faced \nAnd explain why you worked in the group","points":[{"prompt":"What you did","idea":"学校小组做一次关于减少食物浪费的展示"},{"prompt":"Who you worked with","idea":"我和两位同班同学合作，我找例子，他们做问卷和幻灯片"},{"prompt":"What problems you faced","idea":"起初意见不同、资料重复，后来通过统一文件和分工解决"},{"prompt":"And explain why you worked in the group","idea":"任务需要不同能力，合作让内容比一个人做更完整"}],"expressions":{"B1":"divide the work","B2":"resolve differences of opinion","C1":"coordinate complementary strengths"},"angles":["Communication","Strength"]},{"part":"p2","title":"An occasion when you had a special cake","question":"Describe an occasion when you had a special cake. \n \nYou should say: \nWhen this happened \nWhere this happened \nWho gave you the cake \nAnd explain why it was a special cake","points":[{"prompt":"When this happened","idea":"去年生日那天"},{"prompt":"Where this happened","idea":"在朋友家一起过生日"},{"prompt":"Who gave you the cake","idea":"朋友送了手工猫脸蛋糕，她提前练配方，用水果做出我喜欢的图案"},{"prompt":"And explain why it was a special cake","idea":"特别是因为她记住了我的喜好并花时间制作；价格不高却让我感到被重视"}],"expressions":{"B1":"bake a birthday cake","B2":"add a personal touch","C1":"attach sentimental value to a gift"},"angles":["Sentimental","Interest"]},{"part":"p2","title":"A time when you got up early","question":"Describe a time when you got up early. \n \nYou should say: \nWhen it was \nWhat you did \nWhy you got up early \nAnd explain how you felt about it","points":[{"prompt":"When it was","idea":"上周六，我五点半起床"},{"prompt":"What you did","idea":"前一晚收好行李，早晨吃早餐后直接去车站"},{"prompt":"Why you got up early","idea":"为了赶早班火车，车站较远，需要留出路上时间"},{"prompt":"And explain how you felt about it","idea":"开始很困，但按时到站后很安心，也看到安静的清晨"}],"expressions":{"B1":"catch an early train","B2":"leave enough time for the journey","C1":"trade short-term discomfort for peace of mind"},"angles":["Strength","Health"]},{"part":"p2","title":"A film you didn't like","question":"Describe a film you didn't like. \nYou should say: \nWhen you watched it \nWhere you watched it \nWhat it was about \nAnd explain why you don't like it","points":[{"prompt":"When you watched it","idea":"上个月的一个周末"},{"prompt":"Where you watched it","idea":"我在家用电脑看，预告片让我以为会很精彩"},{"prompt":"What it was about","idea":"一部讲宇航员寻找新居住地的科幻电影"},{"prompt":"And explain why you don't like it","idea":"我不喜欢的是故事缺乏说服力，不是因为科幻题材本身"}],"expressions":{"B1":"a confusing ending","B2":"have an unconvincing plot","C1":"prioritise spectacle over character development"},"angles":["Interest","Weakness"]},{"part":"p2","title":"An exciting book you enjoy reading","question":"Describe an exciting book that you enjoy reading. \n \nYou should say: \nWhen you read it \nWhat kind of book it is \nWhat it is about \nAnd explain why you think it is exciting","points":[{"prompt":"When you read it","idea":"去年暑假读的，书名替换成自己真正读过的书"},{"prompt":"What kind of book it is","idea":"是一本侦探小说，每章结尾都会留下疑问"},{"prompt":"What it is about","idea":"侦探通过不起眼的线索寻找失踪的人，新的发现不断改变我对人物的判断"},{"prompt":"And explain why you think it is exciting","idea":"我觉得悬念很强，忍不住想看下一章，也喜欢自己猜结局"}],"expressions":{"B1":"guess what happens next","B2":"keep the reader in suspense","C1":"reveal clues without giving the ending away"},"angles":["Interest","Relaxation"]},{"part":"p2","title":"A gift for your friend","question":"Describe a gift you would like to buy for your friend. \n \nYou should say: \nWhat gift you would like to buy \nWho you would like to give it to \nWhy you want to buy this gift for him/her \nAnd explain why you would like to choose that gift","points":[{"prompt":"What gift you would like to buy","idea":"一个结实的保温水杯，可以在杯上刻名字"},{"prompt":"Who you would like to give it to","idea":"想送给大学室友，他喜欢周末露营和徒步"},{"prompt":"Why you want to buy this gift for him/her","idea":"他的旧杯盖会漏水，我想帮他在户外方便喝水"},{"prompt":"And explain why you would like to choose that gift","idea":"选择它是因为实用、能反复用，也能通过刻字体现我记得他的爱好"}],"expressions":{"B1":"a reusable water bottle","B2":"choose a practical gift","C1":"tailor a gift to someone's everyday needs"},"angles":["Sentimental","Economy"]},{"part":"p2","title":"A law or regulation about environmental protection","question":"Describe a law or regulation about environmental protection. \n \nYou should say: \nWhat it is \nHow you first learned about it \nWho benefits from it \nAnd explain how you feel about this law or regulation","points":[{"prompt":"What it is","idea":"小区实行的垃圾分类规定，具体内容按当地实际替换"},{"prompt":"How you first learned about it","idea":"我第一次通过楼下公告和居民群知道"},{"prompt":"Who benefits from it","idea":"分开放置可回收物便于后续处理，居民和清洁人员都可能受益"},{"prompt":"And explain how you feel about this law or regulation","idea":"居民和清洁人员都可能受益；我支持但希望指示更清楚"}],"expressions":{"B1":"sort household waste","B2":"make recycling more practical","C1":"reduce avoidable environmental harm"},"angles":["Education","Economy"]},{"part":"p2","title":"An ambition that you have had for a long time","question":"Describe an ambition that you have had for a long time \n \nYou should say: \nWhat it is \nWhat you can for it \nWhen you can achieve it \nAnd explain why you have this as an ambition","points":[{"prompt":"What it is","idea":"长期想能独立完成一场英语演讲"},{"prompt":"What you can for it","idea":"我每周练一个话题，录音后修改不清楚的部分"},{"prompt":"When you can achieve it","idea":"希望在明年的活动上尝试，具体时间按自己计划改"},{"prompt":"And explain why you have this as an ambition","idea":"想更自在地表达观点，也为以后教学或工作做准备"}],"expressions":{"B1":"work towards a goal","B2":"track gradual progress","C1":"turn a vague ambition into a concrete plan"},"angles":["Education","Strength"]},{"part":"p2","title":"Something helped you to learn a foreign language","question":"Describe something that helped you learn a foreign language. \n \nYou should say: \nWhat it was \nWhat language you learnt \nWhy you chose to learn that language \nAnd explain how this thing helped you","points":[{"prompt":"What it was","idea":"带字幕的短纪录片，能提供画面和真实语境"},{"prompt":"What language you learnt","idea":"我用它学习英语"},{"prompt":"Why you chose to learn that language","idea":"我选英语是希望能听懂真实内容，并在旅行或交流中使用"},{"prompt":"And explain how this thing helped you","idea":"先看字幕理解，再关字幕反复听重点片段并跟读；画面帮助理解新词"}],"expressions":{"B1":"watch with subtitles","B2":"learn words in context","C1":"bridge the gap between study and real-world use"},"angles":["Education","Interest"]},{"part":"p2","title":"A story/book with animals in it","question":"Describe a story/book with animals in it. \nYou should say: \nWhat animals are in it \nWhat the story/book is about \nWhy you read the story/book \nAnd explain what you think of this story/book","points":[{"prompt":"What animals are in it","idea":"乌龟和兔子，是小时候读过的《龟兔赛跑》"},{"prompt":"What the story/book is about","idea":"兔子跑得快却半途睡觉，乌龟持续前进最后获胜"},{"prompt":"Why you read the story/book","idea":"家人读给我听，用它鼓励我慢慢练习，不急着比较"},{"prompt":"And explain what you think of this story/book","idea":"我喜欢它简单易懂，但现实中努力和方法都重要"}],"expressions":{"B1":"keep going steadily","B2":"learn a lesson from a story","C1":"avoid judging ability by first impressions"},"angles":["Education","Strength"]},{"part":"p2","title":"A TV show/online program you have watched recently","question":"Describe a TV show/online program you have watched recently. \nYou should say: \nWhat it is \nWhat it is about \nHow often you watch it \nAnd explain how you feel about it","points":[{"prompt":"What it is","idea":"最近看的一档做饭节目"},{"prompt":"What it is about","idea":"把做菜拆成准备食材、烹饪和摆盘，也展示常见错误"},{"prompt":"How often you watch it","idea":"我每周看一次，关键动作会暂停，周末试做其中一道"},{"prompt":"And explain how you feel about it","idea":"主持人解释清楚，还展示常见错误，让我觉得实用"}],"expressions":{"B1":"follow a cooking show","B2":"pick up practical techniques","C1":"make specialised knowledge accessible"},"angles":["Education","Relaxation"]},{"part":"p2","title":"An advertisement with a famous person in it","question":"Describe an advertisement with a famous person in it. \nYou should say: \nWho the person is \nWhere you can see it \nWhat the advertisement is about \nAnd explain how you feel about the advertisement","points":[{"prompt":"Who the person is","idea":"一位知名运动员，替换成自己真正看过的代言人"},{"prompt":"Where you can see it","idea":"我在地铁广告牌和在线视频播放前见过"},{"prompt":"What the advertisement is about","idea":"为运动鞋做广告，展示训练动作，突出舒适感和支撑"},{"prompt":"And explain how you feel about the advertisement","idea":"我记住了广告，但会看尺码和评价再买，不因名人直接购买"}],"expressions":{"B1":"a sports-shoe advert","B2":"a celebrity endorsement","C1":"separate brand image from product quality"},"angles":["Communication","Economy"]},{"part":"p2","title":"A kind of food people eat during special event","question":"Describe a kind of food people eat during special event. \nYou should say: \nWhat the food is \nWhat event people usually eat it \nHow it is cooked \nAnd explain why it is for the special event.","points":[{"prompt":"What the food is","idea":"饺子，可以有肉馅或蔬菜馅"},{"prompt":"What event people usually eat it","idea":"我家常在春节准备，具体家庭习惯可以替换"},{"prompt":"How it is cooked","idea":"把馅包进面皮，通常煮熟，也可以煎"},{"prompt":"And explain why it is for the special event.","idea":"它与节日习惯相关，一家人边包边聊天，准备过程也有团聚意义"}],"expressions":{"B1":"make dumplings together","B2":"follow a family tradition","C1":"associate a dish with a shared celebration"},"angles":["Sentimental","Communication"]},{"part":"p2","title":"An interesting video","question":"Describe an interesting video. \nYou should say: \nWhen and where you watched it \nWhat it is about \nWhy you watched it \nAnd explain how you feel about it","points":[{"prompt":"When and where you watched it","idea":"上周在视频平台看了一段修复旧椅子的视频"},{"prompt":"What it is about","idea":"拍摄者展示拆卸、打磨和重新上漆的过程"},{"prompt":"Why you watched it","idea":"因为家里也有旧家具，我想知道能否修复而非丢弃"},{"prompt":"And explain how you feel about it","idea":"前后对比很明显，步骤清楚，让我想自己试试"}],"expressions":{"B1":"restore an old chair","B2":"show a step-by-step process","C1":"make a practical skill visually accessible"},"angles":["Interest","Education"]},{"part":"p2","title":"A new law you would like to introduce in your country","question":"Describe a new law you would like to introduce in your country. \nYou should say: \nWhat law it is \nWhat changes this law brings \nWhether this new law will be popular \nAnd explain how you feel about this","points":[{"prompt":"What law it is","idea":"我想提出更明确的网络广告标识规则，这是一个假设提案"},{"prompt":"What changes this law brings","idea":"付费推广需要清楚标明，并提供容易找到的关闭方式"},{"prompt":"Whether this new law will be popular","idea":"消费者可能欢迎，部分平台可能担心收入或调整成本"},{"prompt":"And explain how you feel about this","idea":"消费者可能欢迎，部分平台可能担心收入；我支持透明度"}],"expressions":{"B1":"label paid adverts clearly","B2":"protect consumer choice","C1":"improve transparency without banning advertising"},"angles":["Communication","Economy"]},{"part":"p2","title":"Somewhere near a natural place","question":"Describe somewhere near a natural place that you have been to. \nYou should say: \nWhere this place is \nWho you went there with \nWhy you went there \nAnd explain how you feel about the place","points":[{"prompt":"Where this place is","idea":"去过一座靠近湖边的小镇，有临湖步道和小咖啡馆"},{"prompt":"Who you went there with","idea":"我和朋友周末去短途旅行"},{"prompt":"Why you went there","idea":"想远离车流，沿湖散步并拍自然照片"},{"prompt":"And explain how you feel about the place","idea":"我喜欢既能接近自然又有方便设施的环境"}],"expressions":{"B1":"walk along the lakeside","B2":"escape the city bustle","C1":"enjoy nature without sacrificing convenience"},"angles":["Relaxation","Health"]},{"part":"p2","title":"A building you like","question":"Describe a building you like. \nYou should say \nWhere it is \nWhat it looks like \nWhat it is used for \nAnd explain why you like it","points":[{"prompt":"Where it is","idea":"家附近的公共图书馆"},{"prompt":"What it looks like","idea":"外面有大窗和简单的浅色墙，里面采光好"},{"prompt":"What it is used for","idea":"供居民借书、自习，也有小型阅读活动"},{"prompt":"And explain why you like it","idea":"我喜欢安静座位和免费资源，它让学习更容易"}],"expressions":{"B1":"a public library","B2":"a well-lit reading space","C1":"provide an accessible community resource"},"angles":["Education","Economy"]},{"part":"p2","title":"A noisy place you have been to","question":"Describe a noisy place you have been to. \n \nYou should say: \nWhat it is \nWhen you went there \nWhat you did there \nAnd explain why you feel it is a noisy place","points":[{"prompt":"What it is","idea":"商场美食区，背景音乐、餐具和人声混在一起"},{"prompt":"When you went there","idea":"上个月一个周末的午餐高峰"},{"prompt":"What you did there","idea":"我和朋友去吃饭，想边吃边聊近况"},{"prompt":"And explain why you feel it is a noisy place","idea":"我们需要提高音量才能聊天，吃完便换到安静地方"}],"expressions":{"B1":"raise my voice","B2":"struggle to hear a conversation","C1":"experience overlapping sources of noise"},"angles":["Communication","Health"]},{"part":"p2","title":"A natural place","question":"Describe a natural place (e.g. a park, a mountain). \nYou should say: \nWhere this place is \nHow you knew this place \nWhat it is like \nAnd explain why you like to visit it","points":[{"prompt":"Where this place is","idea":"家附近一座有步道的小山"},{"prompt":"How you knew this place","idea":"朋友介绍后我周末去过，后来会偶尔再去"},{"prompt":"What it is like","idea":"沿路有树和观景点，早晨能听到鸟叫"},{"prompt":"And explain why you like to visit it","idea":"爬坡让我活动身体，离开屏幕后头脑更清楚"}],"expressions":{"B1":"follow a walking trail","B2":"take a break from screens","C1":"feel mentally restored by natural surroundings"},"angles":["Health","Relaxation"]},{"part":"p2","title":"A crowded place you went to","question":"Describe a crowded place you went to.\nYou should say:\nwhen you went there\nwho you went there with\nwhy you went there\nand explain how you felt about it","points":[{"prompt":"when you went there","idea":"去年假期去热门夜市"},{"prompt":"who you went there with","idea":"和一位同学一起去"},{"prompt":"why you went there","idea":"为了尝当地小吃，也逛手工摊位"},{"prompt":"and explain how you felt about it","idea":"一开始觉得热闹，后来有点累；下次想错开高峰"}],"expressions":{"B1":"queue for street food","B2":"navigate a busy night market","C1":"find the lively atmosphere overwhelming"},"angles":["Relaxation","Weakness"]},{"part":"p2","title":"A city you have been to and would like to visit again","question":"Describe a city you have been to and would like to visit again. \nYou should say: \nWhere it is \nWhen you visited it \nWhat you did there \nAnd explain why you would like to visit it again","points":[{"prompt":"Where it is","idea":"杭州，位于中国东部"},{"prompt":"When you visited it","idea":"去年春天去，和朋友待了两天"},{"prompt":"What you did there","idea":"沿西湖散步、逛街并尝当地食物"},{"prompt":"And explain why you would like to visit it again","idea":"想再去是为了更慢地探索，而不是重复打卡"}],"expressions":{"B1":"walk around the lake","B2":"explore at a slower pace","C1":"revisit a place with a different perspective"},"angles":["Interest","Relaxation"]},{"part":"p2","title":"An important river/lake","question":"Describe an important river/lake in your country. \n \nYou should say: \nWhere it is \nHow big/long it is \nWhat it looks like \nAnd explain why it is important","points":[{"prompt":"Where it is","idea":"杭州城区的西湖"},{"prompt":"How big/long it is","idea":"是一片较大的湖面；如需面积数字，先查证再补充"},{"prompt":"What it looks like","idea":"周围有树和步道，天气好时能看到水面、远山与游船"},{"prompt":"And explain why it is important","idea":"它提供休闲空间，也吸引游客，对居民生活和旅游重要"}],"expressions":{"B1":"a lakeside path","B2":"support local tourism","C1":"serve both recreational and cultural functions"},"angles":["Economy","Relaxation"]},{"part":"p2","title":"A place in your country that you would like to recommend to travelers","question":"Describe a place in your country that you would like to recommend to travelers. \n \nYou should say: \nWhere it is \nWhat it is \nWhat people can do there \nAnd explain why you would like to recommend it to travelers","points":[{"prompt":"Where it is","idea":"杭州的西湖周边"},{"prompt":"What it is","idea":"有湖面、步道和公共休闲空间的区域"},{"prompt":"What people can do there","idea":"游客可以散步、看风景，并了解附近历史建筑"},{"prompt":"And explain why you would like to recommend it to travelers","idea":"适合想慢旅行的人；节假日最好提前安排避开拥挤"}],"expressions":{"B1":"enjoy the lake view","B2":"combine scenery with local culture","C1":"offer a varied experience without a packed itinerary"},"angles":["Interest","Relaxation"]},{"part":"p2","title":"A friend’s home you visited but you don’t want to live there","question":"Describe a friend's home you visited but you don't want to live there \n \nYou should say: \nWhere the home is \nWho this person is \nWhat kind of home it is \nAnd explain why you don't want to live there","points":[{"prompt":"Where the home is","idea":"城市中心的一座高层公寓"},{"prompt":"Who this person is","idea":"住在那里的是我的大学同学，我上个月去做客"},{"prompt":"What kind of home it is","idea":"公寓整洁但面积小、收纳有限，附近交通方便，夜里却有道路声音"},{"prompt":"And explain why you don't want to live there","idea":"我需要安静学习和更多收纳空间，所以适合做客但不适合我长期住"}],"expressions":{"B1":"a small city-centre flat","B2":"have limited storage space","C1":"prioritise a quieter living environment"},"angles":["Health","Personality"]},{"part":"p2","title":"A place you would like to visit in your free time","question":"Describe a place you would like to visit in your free time. \nYou should say: \nWhere it is \nWhat you will do there \nHow long you will stay there \nAnd explain why you would like to visit it","points":[{"prompt":"Where it is","idea":"附近的一家陶艺工作室"},{"prompt":"What you will do there","idea":"会参加体验课，学习揉泥和做杯子，提前预约并穿便于清洗的衣服"},{"prompt":"How long you will stay there","idea":"计划在那里待两小时"},{"prompt":"And explain why you would like to visit it","idea":"喜欢离开手机做点具体东西，成品不完美也能纪念这次体验"}],"expressions":{"B1":"try a pottery class","B2":"enjoy a hands-on activity","C1":"find satisfaction in the process rather than perfection"},"angles":["Interest","Relaxation"]},{"part":"p2","title":"A boring place","question":"Describe a boring place. \nYou should say: \nWhere it is \nWho you went there with \nWhat you did there \nAnd explain why you think it is a boring place","points":[{"prompt":"Where it is","idea":"一次旅行中的车站候车室"},{"prompt":"Who you went there with","idea":"和家人一起去，我们提前到站"},{"prompt":"What you did there","idea":"坐着等了很久，听广播反复播信息，附近没有可参与的活动"},{"prompt":"And explain why you think it is a boring place","idea":"我不觉得车站本身永远无聊，只是当时缺少可参与的事情"}],"expressions":{"B1":"wait for a long time","B2":"have little to keep me occupied","C1":"feel mentally unstimulated in a repetitive setting"},"angles":["Weakness","Relaxation"]},{"part":"p2","title":"Your favorite city that you have visited","question":"Describe your favourite city that you have visited. \nYou should say: \nWhere it is \nHow you knew it \nWhen you visited it \nAnd explain why it is your favourite city","points":[{"prompt":"Where it is","idea":"成都，我最喜欢的一次城市旅行的目的地"},{"prompt":"How you knew it","idea":"通过朋友的旅行照片知道，尤其被公园喝茶的场景吸引"},{"prompt":"When you visited it","idea":"去年秋天去，在公园喝茶、逛小街并尝小吃"},{"prompt":"And explain why it is your favourite city","idea":"我喜欢那次体验中的慢节奏和日常生活感，不概括所有居民"}],"expressions":{"B1":"try local snacks","B2":"enjoy a laid-back atmosphere","C1":"appreciate a city's everyday character"},"angles":["Interest","Relaxation"]},{"part":"p2","title":"A tall building in your city you like or dislike","question":"Describe a tall building in your city you like or dislike. \n \nYou should say: \nWhere it is \nWhat it is used for \nWhat it looks like \nAnd explain why you like or dislike it","points":[{"prompt":"Where it is","idea":"市中心的一座高楼，具体名称可按真实经历替换"},{"prompt":"What it is used for","idea":"玻璃外墙，远远可见，晚上灯光明显"},{"prompt":"What it looks like","idea":"里面有商店和办公室，顶层可看城市景色"},{"prompt":"And explain why you like or dislike it","idea":"评价时同时讲用途和真实体验，不只说高或漂亮"}],"expressions":{"B1":"a glass-fronted tower","B2":"offer panoramic views","C1":"balance efficient land use with everyday comfort"},"angles":["Economy","Personality"]},{"part":"p3","title":"A popular person","question":"Why do some students want to become popular?","zh":"为什么有些学生想变得受欢迎？","idea":"想被接纳、减少孤独；例如新生希望午餐时有人邀请，不能只谈如何出名。","expressions":{"B1":"feel accepted","B2":"seek approval from peers","C1":"derive confidence from social recognition"}},{"part":"p3","title":"A popular person","question":"What kinds of students are more popular at school?","zh":"什么样的学生在学校更受欢迎？","idea":"愿意帮助别人、幽默且善于倾听；举例借笔记或邀请安静的同学参加活动，成绩好不一定等于受欢迎。","expressions":{"B1":"help classmates","B2":"be approachable","C1":"make others feel included"}},{"part":"p3","title":"A popular person","question":"Do you think a good teacher should be popular?","zh":"你觉得好老师应该受欢迎吗？","idea":"先区分学生喜欢与教学有效；亲切能提高参与，但放任纪律可能影响学习。","expressions":{"B1":"explain things clearly","B2":"maintain classroom discipline","C1":"balance rapport with academic expectations"}},{"part":"p3","title":"A popular person","question":"Why are some celebrities not popular?","zh":"为什么有些名人不受欢迎？","idea":"具体讲失信、傲慢或不尊重他人如何损害形象；用假设例子，不传播未经证实的明星丑闻。","expressions":{"B1":"lose people's trust","B2":"damage their public image","C1":"face a loss of credibility"}},{"part":"p3","title":"An athlete/sports team you admire","question":"Should students have physical education and do sports at school?","zh":"学生应该在学校上体育课和做运动吗？","idea":"体育课打断久坐、提供运动机会；团队游戏也教合作，应给身体条件不同的学生替代活动。","expressions":{"B1":"stay active","B2":"reduce study-related stress","C1":"provide inclusive physical education"}},{"part":"p3","title":"An athlete/sports team you admire","question":"What qualities should an athlete have?","zh":"运动员应该具备什么品质？","idea":"自律帮助持续训练，心理韧性帮助面对失利；团队项目还需要沟通，不要只列形容词。","expressions":{"B1":"train regularly","B2":"cope with setbacks","C1":"maintain composure under pressure"}},{"part":"p3","title":"An athlete/sports team you admire","question":"Is talent important in sports?","zh":"天赋在运动中重要吗？","idea":"天赋可能带来速度或协调优势；没有训练仍难提高，用有天赋却不练习的对照说明。","expressions":{"B1":"have natural ability","B2":"gain a competitive advantage","C1":"turn potential into sustained performance"}},{"part":"p3","title":"An athlete/sports team you admire","question":"Is it easy to identify children's talents?","zh":"发现孩子的天赋容易吗？","idea":"儿童接触项目有限，成长速度也不同；没试过网球不能判断没天赋，避免过早定型。","expressions":{"B1":"try different activities","B2":"discover hidden abilities","C1":"avoid premature judgements about potential"}},{"part":"p3","title":"An athlete/sports team you admire","question":"What's the most popular sport in your country?","zh":"你们国家最受欢迎的运动是什么？","idea":"可说自己身边篮球场和同学活动的观察，再提乒乓球或羽毛球；不把个人观察说成全国排名。","expressions":{"B1":"play basketball after school","B2":"be widely played locally","C1":"distinguish personal observation from national trends"}},{"part":"p3","title":"An athlete/sports team you admire","question":"Do you think children should learn different kinds of sports?","zh":"你觉得孩子应该学不同的运动吗？","idea":"游泳、球类训练不同能力，也帮助发现兴趣；小时候先尝试，再根据兴趣选择专长。","expressions":{"B1":"try different sports","B2":"develop coordination","C1":"delay early specialisation"}},{"part":"p3","title":"An athlete/sports team you admire","question":"What can children learn from doing sports?","zh":"孩子能从运动中学到什么？","idea":"输球后继续练、遵守规则、给队友传球；把体育能力与生活中的耐心和合作联系起来。","expressions":{"B1":"learn to work together","B2":"handle winning and losing","C1":"develop transferable social skills"}},{"part":"p3","title":"An athlete/sports team you admire","question":"How is technology used in sports?","zh":"科技在运动中是怎么应用的？","idea":"智能手表记录心率，回放帮助教练找动作问题；电子判线支持裁判，但设备不能代替全部判断。","expressions":{"B1":"track heart rate","B2":"analyse performance data","C1":"improve the precision of officiating"}},{"part":"p3","title":"Someone you have helped to become healthier","question":"Which group pays more attention to health, young people or old people?","zh":"年轻人和老年人，哪个群体更关注健康？","idea":"比较动机：部分老人关心已有问题，部分年轻人关心体能；经济条件与习惯也会影响，避免一刀切。","expressions":{"B1":"care about fitness","B2":"pay attention to prevention","C1":"avoid treating age groups as homogeneous"}},{"part":"p3","title":"Someone you have helped to become healthier","question":"What effect does stress have on health?","zh":"压力对健康有什么影响？","idea":"压力可能扰乱睡眠、饮食和休息；例如考试周熬夜后更难集中，可讲日常观察而非医学诊断。","expressions":{"B1":"sleep badly","B2":"disrupt eating habits","C1":"create a cycle of stress and poor rest"}},{"part":"p3","title":"Someone you have helped to become healthier","question":"Why do some young people neglect their health?","zh":"为什么有些年轻人忽视自己的健康？","idea":"年轻人可能赶作业、低估长期后果或觉得自己能扛；例子是用熬夜换短期完成任务。","expressions":{"B1":"stay up too late","B2":"prioritise immediate deadlines","C1":"underestimate cumulative health risks"}},{"part":"p3","title":"A person who taught you something","question":"Why should children learn new skills?","zh":"为什么孩子应该学新技能？","idea":"生活技能提高独立性，兴趣技能增加自信；如会收拾书包或做简单饭，不只谈考试分数。","expressions":{"B1":"do things independently","B2":"build practical competence","C1":"develop a sense of self-efficacy"}},{"part":"p3","title":"A person who taught you something","question":"How can parents and teachers teach children new skills?","zh":"父母和老师怎样教孩子新技能？","idea":"先示范、拆成小步骤、给孩子尝试机会；学系鞋带时允许慢慢练，比不断替他做更好。","expressions":{"B1":"show them how","B2":"give step-by-step guidance","C1":"offer support without removing autonomy"}},{"part":"p3","title":"A person who taught you something","question":"How do adults learn a new skill?","zh":"成年人怎样学一项新技能？","idea":"成人先设用途和时间，再用课程、导师或实践学习；如为工作每晚练十分钟表格操作。","expressions":{"B1":"learn for work","B2":"fit practice around commitments","C1":"pursue goal-directed learning"}},{"part":"p3","title":"A person who taught you something","question":"What are the differences between learning from a teacher and learning by oneself?","zh":"跟着老师学和自学有什么区别？","idea":"老师能纠错和提供顺序，自学更灵活便宜；复杂技能可先学基础再独立练，不必二选一。","expressions":{"B1":"ask a teacher for help","B2":"receive personalised feedback","C1":"combine structured instruction with independent practice"}}]);
